// Daily Challenge System
// Auto-generated by Daily Leaderboard workflow
const logger = require('./utils.logging');

/**
 * Security: Limits for memory-intensive structures to prevent Memory DoS.
 * Screeps memory is limited to 2MB; unbounded strings can crash the AI.
 */
const MAX_METRIC_LENGTH = 32;
const MAX_NAME_LENGTH = 100;

// ⚡ PERFORMANCE: Hoist challenges array to module scope to avoid re-allocation.
const CHALLENGES = [
    {
        emoji: '🚀',
        name: 'Speed Demon',
        desc: 'Move 500 tiles',
        metric: 'moves',
        target: 500,
    },
    {
        emoji: '⛏️',
        name: 'Mining Master',
        desc: 'Harvest 5000 energy',
        metric: 'harvested',
        target: 5000,
    },
    {
        emoji: '🏭',
        name: 'Architect',
        desc: 'Build 10 structures',
        metric: 'built',
        target: 10,
    },
    {
        emoji: '🔧',
        name: 'Repairman',
        desc: 'Repair 3000 HP',
        metric: 'repaired',
        target: 3000,
    },
    {
        emoji: '🌟',
        name: 'Controller King',
        desc: 'Upgrade 50 times',
        metric: 'upgrades',
        target: 50,
    },
];

const dailyChallenge = {
    init: function () {
        if (!Memory.dailyChallenge || Memory.dailyChallenge.date !== new Date().toDateString()) {
            const today = new Date().toDateString();
            const availableChallenges = CHALLENGES.filter((c) => c.metric !== 'none');
            const selected = availableChallenges[Math.floor(Math.random() * availableChallenges.length)];

            const sanitizedChallenge = {
                emoji: String(selected.emoji || '❓'),
                name: String(selected.name || 'Unknown').substring(0, MAX_NAME_LENGTH),
                desc: String(selected.desc || 'No description').substring(0, 255),
                metric: selected.metric,
                target: Number(selected.target) || 100,
            };

            Memory.dailyChallenge = {
                date: today,
                challenge: sanitizedChallenge,
                progress: 0,
                completed: false,
            };
        }
        return Memory.dailyChallenge;
    },

    getChallenge: function () {
        return this.init();
    },

    updateProgress: function (metric, amount) {
        const challenge = this.init();
        if (!challenge || challenge.completed) return;

        const numericAmount = Number(amount);
        if (isNaN(numericAmount) || !isFinite(numericAmount) || numericAmount < 0) return;

        const sanitizedMetric = String(metric || '').substring(0, MAX_METRIC_LENGTH);

        if (challenge.challenge.metric === sanitizedMetric) {
            challenge.progress += numericAmount;
            if (challenge.progress >= challenge.challenge.target) {
                challenge.completed = true;
                logger.info('CHALLENGE COMPLETED: ' + challenge.challenge.name);
            }
        }
    },

    reset: function () {
        Memory.dailyChallenge = null;
        return this.init();
    },

    displayChallenge: function () {
        const challenge = this.getChallenge();
        const c = challenge.challenge;
        const percent = Math.min(100, Math.floor((challenge.progress / c.target) * 100));
        logger.info(`CHALLENGE: ${c.desc} [${challenge.progress}/${c.target}] (${percent}%)`);
    },
};

module.exports = dailyChallenge;
